sealed class SoundCanvas : Control {
 public List<TraceShape> Shapes=new List<TraceShape>();public PointF Position { get; private set; }public bool HideDrawing;
 public Action<double,double> Explore;public Action Release,KeyRelease;bool pressed;int contact=-1;
 public SoundCanvas(){Position=new PointF(300,225);DoubleBuffered=true;TabStop=true;BackColor=Color.FromArgb(16,26,32);ForeColor=Color.LightGreen;AccessibleName="Lienzo sonoro";AccessibleDescription="Flechas para explorar; Mayúsculas para paso fino; Inicio vuelve al centro; Espacio repite posición; Escape detiene; Tab sale.";AccessibleRole=AccessibleRole.Graphic;}
 RectangleF View {get{float s=Math.Min((ClientSize.Width-20)/600f,(ClientSize.Height-20)/450f);return new RectangleF((ClientSize.Width-600*s)/2,(ClientSize.Height-450*s)/2,600*s,450*s);}}
 void At(Point p){RectangleF v=View;if(!v.Contains(p)){if(Release!=null)Release();return;}MoveLogical((p.X-v.X)*600/v.Width,(p.Y-v.Y)*450/v.Height);}
 public void ResetPosition(){Position=new PointF(300,225);}
 public void MoveLogical(double x,double y){Position=new PointF((float)Math.Max(0,Math.Min(600,x)),(float)Math.Max(0,Math.Min(450,y)));if(Explore!=null)Explore(Position.X,Position.Y);Invalidate();}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);RectangleF v=View;e.Graphics.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;using(Pen border=new Pen(Color.Gray,2))e.Graphics.DrawRectangle(border,v.X,v.Y,v.Width,v.Height);if(!HideDrawing)using(Pen pen=new Pen(ForeColor,3)){foreach(TraceShape s in Shapes){PointF[] pts=Array.ConvertAll(s.Points,p=>new PointF(v.X+p.X*v.Width/600,v.Y+p.Y*v.Height/450));pen.Color=s.Hole?Color.Orange:ForeColor;if(pts.Length==1)e.Graphics.DrawEllipse(pen,pts[0].X-4,pts[0].Y-4,8,8);else if(pts.Length>1){e.Graphics.DrawLines(pen,pts);if(s.Closed)e.Graphics.DrawLine(pen,pts[pts.Length-1],pts[0]);}}}float x=v.X+Position.X*v.Width/600,y=v.Y+Position.Y*v.Height/450;using(Pen cursor=new Pen(Color.White,2)){e.Graphics.DrawLine(cursor,x-7,y,x+7,y);e.Graphics.DrawLine(cursor,x,y-7,x,y+7);}if(Focused)ControlPaint.DrawFocusRectangle(e.Graphics,ClientRectangle);}
 protected override bool IsInputKey(Keys k){Keys n=k&Keys.KeyCode;return n==Keys.Left||n==Keys.Right||n==Keys.Up||n==Keys.Down||n==Keys.Home||n==Keys.Space||base.IsInputKey(k);}
 protected override void OnKeyDown(KeyEventArgs e){base.OnKeyDown(e);int step=e.Shift?2:e.Control?30:10;PointF p=Position;bool handled=true;switch(e.KeyCode){case Keys.Left:p.X-=step;break;case Keys.Right:p.X+=step;break;case Keys.Up:p.Y-=step;break;case Keys.Down:p.Y+=step;break;case Keys.Home:p=new PointF(300,225);break;case Keys.Space:break;case Keys.Escape:if(Release!=null)Release();e.Handled=true;return;default:handled=false;break;}if(handled){MoveLogical(p.X,p.Y);e.Handled=true;}}
 protected override void OnKeyPress(KeyPressEventArgs e){base.OnKeyPress(e);e.Handled=true;}
 protected override void OnKeyUp(KeyEventArgs e){base.OnKeyUp(e);if(e.KeyCode==Keys.Left||e.KeyCode==Keys.Right||e.KeyCode==Keys.Up||e.KeyCode==Keys.Down||e.KeyCode==Keys.Home||e.KeyCode==Keys.Space)if(KeyRelease!=null)KeyRelease();}
 protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button==MouseButtons.Left){Focus();pressed=true;Capture=true;At(e.Location);}}
 protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(pressed)At(e.Location);}
 protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);pressed=false;Capture=false;if(Release!=null)Release();}
 protected override void OnLostFocus(EventArgs e){base.OnLostFocus(e);pressed=false;Capture=false;if(Release!=null)Release();Invalidate();}
 protected override void OnGotFocus(EventArgs e){base.OnGotFocus(e);Invalidate();}
 [StructLayout(LayoutKind.Sequential)]struct TouchInput{public int x,y;public IntPtr source;public uint id,flags,mask,time;public UIntPtr extra;public uint cx,cy;}
 [DllImport("user32.dll")]static extern bool RegisterTouchWindow(IntPtr h,uint flags);
 [DllImport("user32.dll")]static extern bool GetTouchInputInfo(IntPtr h,int count,[In,Out] TouchInput[] inputs,int size);
 [DllImport("user32.dll")]static extern bool CloseTouchInputHandle(IntPtr h);
 protected override void OnHandleCreated(EventArgs e){base.OnHandleCreated(e);RegisterTouchWindow(Handle,0);}
 protected override void WndProc(ref Message m){if(m.Msg==0x0240){int n=m.WParam.ToInt32()&65535;TouchInput[] data=new TouchInput[n];try{if(GetTouchInputInfo(m.LParam,n,data,Marshal.SizeOf(typeof(TouchInput))))foreach(TouchInput t in data){if((t.flags&2)!=0&&contact<0){contact=(int)t.id;Focus();}if(contact==(int)t.id){if((t.flags&4)!=0){contact=-1;if(Release!=null)Release();}else At(PointToClient(new Point(t.x/100,t.y/100)));}}}finally{CloseTouchInputHandle(m.LParam);}m.Result=IntPtr.Zero;return;}base.WndProc(ref m);}
}

static class Pad {
 [StructLayout(LayoutKind.Sequential)]public struct Gamepad{public ushort buttons;public byte lt,rt;public short lx,ly,rx,ry;}
 [StructLayout(LayoutKind.Sequential)]public struct State{public uint packet;public Gamepad gamepad;}
 [StructLayout(LayoutKind.Sequential)]struct Vibration{public ushort left,right;}
 [StructLayout(LayoutKind.Sequential)]struct Caps{public byte type,subtype;public ushort flags;public Gamepad gamepad;public Vibration vibration;}
 [DllImport("xinput1_4.dll")]static extern uint XInputGetState(uint index,out State state);
 [DllImport("xinput1_4.dll")]static extern uint XInputGetCapabilities(uint index,uint flags,out Caps caps);
 [DllImport("xinput1_4.dll")]static extern uint XInputSetState(uint index,ref Vibration vibration);
 public static int Index=-1;public static bool Rumble;
 public static string Detect(){Stop();Index=-1;Rumble=false;try{for(uint i=0;i<4;i++){Caps c;if(XInputGetCapabilities(i,0,out c)==0){Index=(int)i;Rumble=(c.flags&1)!=0;return "Mando XInput "+(i+1)+(Rumble?": vibración disponible.":": no declara vibración compatible.");}}return "No se detectó ningún mando XInput. Puedes seguir con teclado, ratón o pantalla táctil.";}catch(DllNotFoundException){return "XInput no está disponible en este Windows.";}}
 public static bool Read(out State s){s=new State();try{return Index>=0&&XInputGetState((uint)Index,out s)==0;}catch{return false;}}
 public static bool Vibrate(ushort strength){try{if(Index<0||!Rumble)return false;Vibration v=new Vibration();v.left=strength;v.right=(ushort)(strength/2);return XInputSetState((uint)Index,ref v)==0;}catch{return false;}}
 public static void Stop(){try{if(Index>=0){Vibration v=new Vibration();XInputSetState((uint)Index,ref v);}}catch{}}
}

