 static string B64(string s){return Convert.ToBase64String(Encoding.UTF8.GetBytes(s));}static string Decode(string s){return Encoding.UTF8.GetString(Convert.FromBase64String(s));}
 void StartEngine(){try{var info=new ProcessStartInfo(Path.Combine(home,"runtime","bin","java.exe"),"-Xms16m -Xmx160m -cp \""+Path.Combine(home,"formas-engine.jar")+"\" DesktopEngine \""+Path.Combine(home,"kemar.bin")+"\""+(smoke?" --silent":""));info.UseShellExecute=false;info.CreateNoWindow=true;info.RedirectStandardInput=true;info.RedirectStandardOutput=true;info.RedirectStandardError=true;info.StandardOutputEncoding=Encoding.UTF8;engine=new Process();engine.StartInfo=info;engine.EnableRaisingEvents=true;engine.OutputDataReceived+=(s,e)=>{if(e.Data!=null&&!closing)try{BeginInvoke((Action)(()=>Receive(e.Data)));}catch{}};engine.ErrorDataReceived+=(s,e)=>{};engine.Exited+=(s,e)=>{if(!closing)try{BeginInvoke((Action)(()=>{ready=false;Say("El motor se cerró. Vuelve a abrir la aplicación.");}));}catch{}};engine.Start();pipe=engine.StandardInput;pipe.AutoFlush=true;engine.BeginOutputReadLine();engine.BeginErrorReadLine();}catch(Exception e){Say("No se pudo iniciar el motor incluido: "+e.Message);if(smoke){Environment.ExitCode=1;Close();}}}
 void Send(string s){if(pipe==null||closing)return;try{pipe.WriteLine(s);}catch{ready=false;Say("El motor no responde. Vuelve a abrir la aplicación.");}}
 void Receive(string line){try{string[] a=line.Split('|');switch(a[0]){case "LESSON":lessons.Items.Add(Decode(a[1]));hints.Add(Decode(a[2]));break;case "READY":ready=true;loading=true;lessons.SelectedIndex=Math.Min(savedLesson,lessons.Items.Count-1);loading=false;Settings();Guide();Say("Listo. Elige una actividad o enfoca el lienzo.");break;case "SCENE":sceneCount++;description.Text=Decode(a[1]);canvas.Shapes=ParseShapes(a.Length>2?a[2]:"");canvas.ResetPosition();canvas.Invalidate();Say(description.Text);Log("scene");break;case "FEEDBACK":feedbackKind=a[1];int c=int.Parse(a[2],CultureInfo.InvariantCulture);bool boundary=feedbackKind=="line"||feedbackKind=="vertex"||feedbackKind=="region"||feedbackKind=="frame";if(boundary&&haptics.Checked&&c!=feedbackComponent){if(Pad.Vibrate(10000))rumbleEnd=DateTime.UtcNow.AddMilliseconds(65);}feedbackComponent=boundary?c:-2;break;case "DESCRIPTION":string d=Decode(a[1]);Say(d);break;case "STATUS":case "ERROR":Say(Decode(a[1]));break;case "AUDIOERROR":audioError=Decode(a[1]);Say(audioError);break;case "IMAGEDONE":string f=Decode(a[1]);if(temporary.Contains(f)){try{File.Delete(f);}catch{}temporary.Remove(f);}break;}}catch{Say("La respuesta del motor no fue compatible.");}}
 static List<TraceShape> ParseShapes(string value){var list=new List<TraceShape>();foreach(string shape in value.Split('/')){if(shape.Length==0)continue;string[] pair=shape.Split(':');string[] flags=pair[0].Split(',');var points=new List<PointF>();foreach(string p in pair[1].Split(';')){if(p.Length==0)continue;string[] xy=p.Split(',');points.Add(new PointF(float.Parse(xy[0],CultureInfo.InvariantCulture),float.Parse(xy[1],CultureInfo.InvariantCulture)));}list.Add(new TraceShape{Closed=flags[0]=="1",Hole=flags[1]=="1",Points=points.ToArray()});}return list;}
 void Guide(){if(!ready||lessons.SelectedIndex<0)return;Stop();imageScene=false;sourceId="";seed="";element=0;Send("GUIDE|"+lessons.SelectedIndex+"|"+variant+"|"+separation.Value);SavePreferences();Log("guided_activity");}
 void PlayElement(){Stop();Send("ELEMENT|"+level.SelectedIndex+"|"+element);Log("element");}
 void Touch(double x,double y){if(!ready)return;long now=elapsed.ElapsedMilliseconds;if(now-lastTouch<18)return;lastTouch=now;Send("TOUCH|"+x.ToString(CultureInfo.InvariantCulture)+"|"+y.ToString(CultureInfo.InvariantCulture));}
 void Stop(){if(voice!=null)try{voice.SpeakAsyncCancelAll();}catch{}Send("STOP");Pad.Stop();padMoving=false;feedbackComponent=-2;}
 void Say(string s){status.Text=s;status.AccessibleName=s;}
 void Speak(string s){Say(s);if(narration.Checked&&voice!=null){voice.SpeakAsyncCancelAll();voice.SpeakAsync(s);}}
 Dictionary<string,object> AudioSettings(){return new Dictionary<string,object>{{"spatial",spatial.SelectedIndex},{"profile",profile.SelectedIndex},{"volume",volume.Value},{"monoLateral",lateral.Checked},{"monoAmount",amount.Value},{"speed",speed.Value},{"brightness",brightness.Value},{"width",width.Value},{"elevation",elevation.Value},{"surface",surface.SelectedIndex},{"air",air.Checked},{"markers",markers.Checked},{"swap",swap.Checked},{"tolerance",tolerance.Value},{"haptics",haptics.Checked}};}
 void Settings(){if(!ready)return;Send("SET|"+profile.SelectedIndex+"|"+spatial.SelectedIndex+"|"+Dec(volume.Value/100)+"|"+lateral.Checked.ToString().ToLowerInvariant()+"|"+Dec(amount.Value/100)+"|"+Dec(speed.Value/100)+"|"+Dec(brightness.Value/100)+"|"+width.Value+"|"+elevation.Value+"|"+markers.Checked.ToString().ToLowerInvariant()+"|"+swap.Checked.ToString().ToLowerInvariant()+"|"+surface.SelectedIndex+"|"+air.Checked.ToString().ToLowerInvariant()+"|"+tolerance.Value);SavePreferences();Log("sound_settings");}
 static string Dec(decimal n){return n.ToString(CultureInfo.InvariantCulture);}
 void Demo(int n){Stop();imageScene=true;sourceId=Guid.NewGuid().ToString("N");Send("DEMO|"+n);Log("image_demo_"+n);}
 void ImportImage(){using(var dialog=new OpenFileDialog()){dialog.Filter="Imágenes|*.png;*.jpg;*.jpeg;*.bmp;*.gif|Todos los archivos|*.*";if(dialog.ShowDialog(this)!=DialogResult.OK)return;try{Stop();string temp=Path.Combine(storage,"import-"+Guid.NewGuid().ToString("N")+".png");using(Image original=Image.FromFile(dialog.FileName)){if((long)original.Width*original.Height>80000000)throw new InvalidDataException("La imagen supera el límite de 80 megapíxeles.");try{if(Array.IndexOf(original.PropertyIdList,0x112)>=0){int o=original.GetPropertyItem(0x112).Value[0];RotateFlipType[] map={RotateFlipType.RotateNoneFlipNone,RotateFlipType.RotateNoneFlipNone,RotateFlipType.RotateNoneFlipX,RotateFlipType.Rotate180FlipNone,RotateFlipType.Rotate180FlipX,RotateFlipType.Rotate90FlipX,RotateFlipType.Rotate90FlipNone,RotateFlipType.Rotate270FlipX,RotateFlipType.Rotate270FlipNone};if(o>0&&o<map.Length)original.RotateFlip(map[o]);}}catch{}double scale=Math.Min(1,768.0/Math.Max(original.Width,original.Height));using(Bitmap small=new Bitmap(Math.Max(2,(int)(original.Width*scale)),Math.Max(2,(int)(original.Height*scale)))){using(Graphics g=Graphics.FromImage(small)){g.Clear(Color.White);g.DrawImage(original,0,0,small.Width,small.Height);}small.Save(temp,ImageFormat.Png);}}temporary.Add(temp);imageScene=true;sourceId=Guid.NewGuid().ToString("N");Send("IMAGE|"+B64(temp)+"|"+imageMode.SelectedIndex+"|"+new int[]{128,192,256}[imageResolution.SelectedIndex]+"|"+offset.Value);Log("image_import");}catch(Exception e){Say("No se pudo importar: "+e.Message);}}}
 Dictionary<string,object> Session(){return new Dictionary<string,object>{{"schema",1},{"version",Version},{"id",sessionId},{"events",events}};}
 void Log(string type){if(loading||events.Count>=20000)return;events.Add(new Dictionary<string,object>{{"type",type},{"t",elapsed.ElapsedMilliseconds},{"source",imageScene?"image":"geometry"},{"sourceId",imageScene?sourceId:""},{"lesson",imageScene?-1:lessons.SelectedIndex},{"variant",variant},{"seed",imageScene?"external":seed},{"settings",AudioSettings()}});try{File.WriteAllText(Path.Combine(storage,"session-current.json"),json.Serialize(Session()),Encoding.UTF8);}catch{}}
 void Export(){using(var dialog=new SaveFileDialog()){dialog.Filter="Sesión JSON|*.json";dialog.FileName="formas-windows-"+DateTime.Now.ToString("yyyyMMdd-HHmm")+".json";if(dialog.ShowDialog(this)==DialogResult.OK)try{File.WriteAllText(dialog.FileName,json.Serialize(Session()),Encoding.UTF8);Say("Sesión exportada. No incluye imágenes ni sus contornos.");}catch(Exception e){Say("No se pudo guardar: "+e.Message);}}}
 int savedLesson=0;
 void SavePreferences(){if(loading)return;try{var d=AudioSettings();d["lesson"]=lessons.SelectedIndex;d["narration"]=narration.Checked;d["padInput"]=padInput.Checked;File.WriteAllText(Path.Combine(storage,"preferences.json"),json.Serialize(d),Encoding.UTF8);}catch{}}
 void LoadPreferences(){try{var d=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(storage,"preferences.json")));Action<string,NumericUpDown> n=(k,c)=>{if(d.ContainsKey(k))c.Value=Math.Max(c.Minimum,Math.Min(c.Maximum,Convert.ToDecimal(d[k],CultureInfo.InvariantCulture)));};Action<string,ComboBox> i=(k,c)=>{if(d.ContainsKey(k))c.SelectedIndex=Math.Max(0,Math.Min(c.Items.Count-1,Convert.ToInt32(d[k])));};Action<string,CheckBox> b=(k,c)=>{if(d.ContainsKey(k))c.Checked=Convert.ToBoolean(d[k]);};n("volume",volume);n("monoAmount",amount);n("speed",speed);n("brightness",brightness);n("width",width);n("elevation",elevation);n("tolerance",tolerance);i("spatial",spatial);i("profile",profile);i("surface",surface);b("monoLateral",lateral);b("air",air);b("markers",markers);b("swap",swap);b("narration",narration);b("padInput",padInput);if(d.ContainsKey("lesson"))savedLesson=Math.Max(0,Math.Min(28,Convert.ToInt32(d["lesson"])));/* Rumble deliberately requires activation each run. */}catch{}}
 void Tick(object sender,EventArgs e){if(DateTime.UtcNow>=rumbleEnd){Pad.Stop();rumbleEnd=DateTime.MaxValue;}if(ready&&padInput.Checked&&canvas.Focused){Pad.State s;if(Pad.Read(out s)){int dx=0,dy=0;ushort b=s.gamepad.buttons;if((b&4)!=0)dx=-1;if((b&8)!=0)dx=1;if((b&1)!=0)dy=-1;if((b&2)!=0)dy=1;double ax=Math.Abs((int)s.gamepad.lx)>9000?s.gamepad.lx/32768.0:0,ay=Math.Abs((int)s.gamepad.ly)>9000?-s.gamepad.ly/32768.0:0;if(dx!=0||dy!=0||ax!=0||ay!=0){canvas.MoveLogical(canvas.Position.X+dx*5+ax*7,canvas.Position.Y+dy*5+ay*7);padMoving=true;}else if(padMoving)Stop();}else if(padMoving)Stop();}if(smoke)SmokeTick();}
 void SmokeTick(){smokeTicks++;if(smokeTicks>500){File.WriteAllText(Path.Combine(home,"smoke-result.txt"),"FAIL timeout stage "+smokeStage);Environment.ExitCode=1;Close();return;}if(!ready)return;switch(smokeStage){case 0:if(sceneCount<1)return;if(lessons.Items.Count!=29)throw new Exception("Expected 29 lessons");loading=true;lessons.SelectedIndex=20;loading=false;Guide();smokeStage=1;break;case 1:if(sceneCount<2)return;canvas.MoveLogical(300,225);Settings();Send("CONTOUR");Send("STOP");Demo(1);smokeStage=2;break;case 2:if(sceneCount<3)return;if(canvas.Shapes.Count!=2||!canvas.Shapes.Exists(s=>s.Hole))throw new Exception("Image hole missing");string exported=json.Serialize(Session());if(exported.Contains("Points")||exported.Contains("import-"))throw new Exception("Image metadata leak");Send("QUIT");File.WriteAllText(Path.Combine(home,"smoke-result.txt"),"PASS: native form, 29 lessons, local engine pipe, triangle scene, image with hole, settings, command playback and anonymous session export. Audio device not exercised in silent smoke test.");Close();break;}}
 void Shutdown(){if(closing)return;Stop();SavePreferences();Send("QUIT");closing=true;timer.Stop();Pad.Stop();foreach(string f in temporary)try{File.Delete(f);}catch{}if(voice!=null)voice.Dispose();if(engine!=null)try{if(!engine.WaitForExit(1200))engine.Kill();engine.Dispose();}catch{}}
}
static class Program {
 [STAThread]static void Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.SetUnhandledExceptionMode(UnhandledExceptionMode.CatchException);Application.ThreadException+=(s,e)=>{if(args.Length>0&&args[0]=="--smoke-test"){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"smoke-result.txt"),"FAIL: "+e.Exception);Environment.Exit(1);}else MessageBox.Show("No se pudo continuar: "+e.Exception.Message,"Formas al oído");};Application.Run(new FormasForm(args.Length>0&&args[0]=="--smoke-test"));}
}
